#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>

std::string formatRow(const std::string& name, int score) {
    std::ostringstream out;
    out << std::left << std::setw(10) << name;
    out << std::right << std::setw(5) << score;
    return out.str();
}

int main() {
    std::string name;
    int score;
    std::cin >> name >> score;
    std::cout << formatRow(name, score) << "\n";
    return 0;
}

